import app from 'flarum/forum/app';
import GiveawayCard from '../components/GiveawayCard';
const cache = new Map();
let pending = new Map();
let timer = 0;

/**
 * Every giveaway link the page shows is looked up in one request, through the
 * same list endpoint, query and visibility as the giveaways page. A giveaway
 * that does not come back (deleted, or not visible to this viewer) leaves its
 * link as a plain link.
 */
function flush() {
  const batch = pending;
  pending = new Map();
  timer = 0;
  const keys = [...batch.keys()];
  for (let i = 0; i < keys.length; i += 20) {
    const chunk = keys.slice(i, i + 20);
    app.request({
      method: 'GET',
      url: app.forum.attribute('apiUrl') + '/giveaways',
      params: {
        filter: {
          slug: chunk.join(',')
        }
      }
    }).then(({
      data
    }) => chunk.forEach(key => batch.get(key)(data.find(g => g.slug === key) || data.find(g => String(g.id) === key) || null)), () => chunk.forEach(key => batch.get(key)(null)));
  }
}
function lookup(key) {
  let found = cache.get(key);
  if (!found) {
    found = new Promise(resolve => pending.set(key, resolve));
    cache.set(key, found);
    timer ||= window.setTimeout(flush, 0);
  }
  return found;
}
export default function embed(links) {
  links.forEach(([a, key]) => lookup(key).then(g => {
    if (!g || !a.isConnected) return;
    const holder = document.createElement('span');
    holder.className = 'GiveawayEmbed';
    a.replaceWith(holder);
    m.render(holder, m(GiveawayCard, {
      giveaway: g
    }));
  }));
}
flarum.reg.add('ernestdefoe-giveaways', 'forum/embed/embed', embed);